<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Ubuntu Desktop</title>
<style>
  *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

  html, body {
    width: 100%;
    height: 100%;
    overflow: hidden;
    font-family: 'Ubuntu', 'Segoe UI', 'Cantarell', system-ui, sans-serif;
    background: #300a24;
  }

  #desktop {
    position: relative;
    width: 100vw;
    height: 100vh;
    background:
      radial-gradient(ellipse at 20% 50%, rgba(233, 84, 32, 0.18) 0%, transparent 50%),
      radial-gradient(ellipse at 80% 20%, rgba(119, 33, 111, 0.4) 0%, transparent 45%),
      radial-gradient(ellipse at 60% 80%, rgba(46, 52, 64, 0.5) 0%, transparent 40%),
      linear-gradient(160deg, #2c001e 0%, #4a1030 35%, #300a24 70%, #1a0510 100%);
    overflow: hidden;
    user-select: none;
  }

  /* Top panel (Ubuntu style) */
  #top-panel {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 28px;
    background: rgba(0, 0, 0, 0.72);
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 12px;
    z-index: 9000;
    color: #eee;
    font-size: 13px;
    backdrop-filter: blur(8px);
  }

  #top-panel .panel-left { display: flex; align-items: center; gap: 10px; }
  #top-panel .activities {
    font-weight: 600;
    letter-spacing: 0.02em;
    padding: 2px 8px;
    border-radius: 4px;
  }
  #top-panel .clock { font-variant-numeric: tabular-nums; opacity: 0.95; }

  /* Dock / taskbar */
  #taskbar {
    position: absolute;
    left: 50%;
    bottom: 12px;
    transform: translateX(-50%);
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 14px;
    background: rgba(20, 10, 18, 0.78);
    border: 1px solid rgba(255, 255, 255, 0.08);
    border-radius: 16px;
    backdrop-filter: blur(16px);
    box-shadow: 0 8px 32px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255,255,255,0.06);
    z-index: 8000;
  }

  #taskbar button {
    width: 52px;
    height: 52px;
    border: none;
    border-radius: 12px;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    background: rgba(255, 255, 255, 0.06);
    transition: background 0.15s, transform 0.15s, box-shadow 0.15s;
    position: relative;
    color: #fff;
  }

  #taskbar button:hover {
    background: rgba(233, 84, 32, 0.35);
    transform: translateY(-4px);
    box-shadow: 0 6px 16px rgba(0,0,0,0.35);
  }

  #taskbar button:active { transform: translateY(-2px) scale(0.96); }

  #taskbar button svg { width: 30px; height: 30px; pointer-events: none; }

  #taskbar button::after {
    content: '';
    position: absolute;
    bottom: 3px;
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: transparent;
    transition: background 0.15s;
  }

  #taskbar button.active::after { background: #e95420; }

  /* Windows */
  .window {
    position: absolute;
    min-width: 360px;
    min-height: 240px;
    width: 640px;
    height: 420px;
    background: #2b2b2b;
    border-radius: 10px;
    box-shadow:
      0 24px 60px rgba(0, 0, 0, 0.55),
      0 0 0 1px rgba(255, 255, 255, 0.06);
    display: none;
    flex-direction: column;
    overflow: hidden;
    z-index: 100;
  }

  .window.visible {
    display: flex;
  }

  .window.focused {
    z-index: 200;
    box-shadow:
      0 28px 70px rgba(0, 0, 0, 0.6),
      0 0 0 1px rgba(233, 84, 32, 0.25);
  }

  .win-titlebar {
    height: 40px;
    background: linear-gradient(180deg, #3d3d3d 0%, #323232 100%);
    display: flex;
    align-items: center;
    padding: 0 12px;
    gap: 10px;
    cursor: grab;
    flex-shrink: 0;
    border-bottom: 1px solid rgba(0,0,0,0.35);
  }

  .win-titlebar:active { cursor: grabbing; }

  .win-controls {
    display: flex;
    gap: 8px;
    align-items: center;
  }

  .win-btn {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    border: none;
    cursor: pointer;
    padding: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: filter 0.12s;
  }

  .win-btn:hover { filter: brightness(1.15); }

  .win-close { background: #e95420; }
  .win-min { background: #eda711; }
  .win-max { background: #7cbf2a; }

  .win-title {
    flex: 1;
    text-align: center;
    color: #ddd;
    font-size: 13px;
    font-weight: 500;
    pointer-events: none;
    margin-right: 48px;
  }

  .win-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: #242424;
    min-height: 0;
  }

  /* Files app */
  #files-toolbar {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 8px 12px;
    background: #2e2e2e;
    border-bottom: 1px solid #1a1a1a;
    flex-shrink: 0;
  }

  #files-up {
    background: #3a3a3a;
    border: 1px solid #4a4a4a;
    color: #eee;
    border-radius: 6px;
    padding: 5px 12px;
    cursor: pointer;
    font-size: 13px;
    transition: background 0.12s;
  }

  #files-up:hover { background: #4a4a4a; }
  #files-up:disabled { opacity: 0.4; cursor: default; }

  #files-path {
    flex: 1;
    background: #1e1e1e;
    border: 1px solid #3a3a3a;
    border-radius: 6px;
    color: #e0e0e0;
    padding: 6px 12px;
    font-size: 13px;
    font-family: 'Ubuntu Mono', 'Consolas', monospace;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  #files-listing {
    flex: 1;
    overflow-y: auto;
    padding: 12px;
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(100px, 1fr));
    gap: 8px;
    align-content: start;
    min-height: 120px;
  }

  .fs-item {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 6px;
    padding: 12px 8px;
    border-radius: 8px;
    cursor: pointer;
    color: #e8e8e8;
    font-size: 12px;
    text-align: center;
    word-break: break-word;
    border: 1px solid transparent;
    transition: background 0.1s;
  }

  .fs-item:hover {
    background: rgba(233, 84, 32, 0.18);
    border-color: rgba(233, 84, 32, 0.3);
  }

  .fs-item.selected {
    background: rgba(233, 84, 32, 0.28);
    border-color: rgba(233, 84, 32, 0.5);
  }

  .fs-icon {
    width: 48px;
    height: 48px;
    display: flex;
    align-items: center;
    justify-content: center;
  }

  .fs-icon svg { width: 44px; height: 44px; }

  /* Notepad */
  #notepad-toolbar {
    display: flex;
    align-items: stretch;
    background: #2e2e2e;
    border-bottom: 1px solid #1a1a1a;
    flex-shrink: 0;
    min-height: 36px;
  }

  #tabs {
    display: flex;
    flex: 1;
    overflow-x: auto;
    gap: 2px;
    padding: 4px 4px 0;
    align-items: flex-end;
  }

  .tab {
    padding: 6px 14px;
    background: #383838;
    color: #bbb;
    border-radius: 6px 6px 0 0;
    font-size: 12px;
    cursor: pointer;
    white-space: nowrap;
    border: 1px solid #1a1a1a;
    border-bottom: none;
    max-width: 140px;
    overflow: hidden;
    text-overflow: ellipsis;
    display: flex;
    align-items: center;
    gap: 8px;
    user-select: none;
    transition: background 0.1s, color 0.1s;
  }

  .tab:hover { background: #424242; color: #ddd; }

  .tab.active {
    background: #242424;
    color: #fff;
    font-weight: 500;
  }

  .tab-close {
    width: 16px;
    height: 16px;
    border-radius: 4px;
    border: none;
    background: transparent;
    color: #999;
    cursor: pointer;
    font-size: 14px;
    line-height: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 0;
    flex-shrink: 0;
  }

  .tab-close:hover { background: rgba(255,80,80,0.35); color: #fff; }

  #new-tab {
    background: transparent;
    border: none;
    color: #ccc;
    font-size: 18px;
    padding: 4px 12px;
    cursor: pointer;
    align-self: center;
    border-radius: 4px;
    line-height: 1;
    margin: 0 4px;
  }

  #new-tab:hover { background: rgba(255,255,255,0.1); color: #fff; }

  #editor {
    flex: 1;
    width: 100%;
    min-height: 120px;
    border: none;
    outline: none;
    resize: none;
    background: #1e1e1e;
    color: #e0e0e0;
    font-family: 'Ubuntu Mono', 'Consolas', 'Courier New', monospace;
    font-size: 14px;
    line-height: 1.55;
    padding: 14px 16px;
    tab-size: 4;
  }

  #editor::placeholder { color: #666; }

  /* Desktop icons decoration */
  .desk-icons {
    position: absolute;
    top: 48px;
    left: 20px;
    display: flex;
    flex-direction: column;
    gap: 16px;
    z-index: 1;
  }

  .desk-icon {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 4px;
    width: 72px;
    color: #f0f0f0;
    font-size: 11px;
    text-shadow: 0 1px 3px rgba(0,0,0,0.8);
    cursor: default;
    padding: 6px;
    border-radius: 6px;
  }

  .desk-icon:hover { background: rgba(255,255,255,0.08); }

  .desk-icon svg { width: 40px; height: 40px; filter: drop-shadow(0 2px 4px rgba(0,0,0,0.4)); }
</style>
</head>
<body>
<div id="desktop">
  <div id="top-panel">
    <div class="panel-left">
      <span class="activities">Activities</span>
