    <div class="clock" id="clock"></div>
  </div>

  <div class="desk-icons">
    <div class="desk-icon">
      <svg viewBox="0 0 48 48" fill="none"><rect x="6" y="10" width="36" height="28" rx="3" fill="#e95420"/><rect x="10" y="16" width="28" height="16" fill="#2c001e"/><rect x="18" y="38" width="12" height="3" fill="#ccc"/><rect x="14" y="41" width="20" height="2" rx="1" fill="#aaa"/></svg>
      <span>Computer</span>
    </div>
