      <svg viewBox="0 0 48 48" fill="none"><path d="M8 14h32a2 2 0 012 2v22a2 2 0 01-2 2H8a2 2 0 01-2-2V16a2 2 0 012-2z" fill="#dda76a"/><path d="M8 14l2-6h12l2 6" fill="#c4893f"/></svg>
