<script>
(function () {
  'use strict';

  /* ---------- Clock ---------- */
  function updateClock() {
    const el = document.getElementById('clock');
    const now = new Date();
    const opts = { weekday: 'short', month: 'short', day: 'numeric', hour: '2-digit', minute: '2-digit' };
    el.textContent = now.toLocaleString(undefined, opts);
  }
  updateClock();
  setInterval(updateClock, 15000);

  /* ---------- Window management ---------- */
  let zCounter = 200;

  function showWindow(id) {
    const win = document.getElementById(id);
    win.classList.add('visible');
    focusWindow(win);
    updateDockIndicators();
  }

  function hideWindow(win) {
    win.classList.remove('visible', 'focused');
    updateDockIndicators();
  }

  function focusWindow(win) {
    document.querySelectorAll('.window').forEach(w => w.classList.remove('focused'));
    win.classList.add('focused');
    zCounter += 1;
    win.style.zIndex = zCounter;
  }

  function updateDockIndicators() {
    document.getElementById('open-files').classList.toggle(
      'active',
      document.getElementById('files-window').classList.contains('visible')
    );
    document.getElementById('open-notepad').classList.toggle(
      'active',
      document.getElementById('notepad-window').classList.contains('visible')
    );
  }

  document.getElementById('open-files').addEventListener('click', () => showWindow('files-window'));
  document.getElementById('open-notepad').addEventListener('click', () => {
    showWindow('notepad-window');
    ensureTabsLoaded();
  });

  document.querySelectorAll('.window').forEach(win => {
    win.addEventListener('mousedown', () => focusWindow(win));

    const closeBtn = win.querySelector('.win-close');
    closeBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      hideWindow(win);
    });
  });

  /* Drag windows */
  document.querySelectorAll('.win-titlebar').forEach(bar => {
    let dragging = false, ox = 0, oy = 0;
    bar.addEventListener('mousedown', (e) => {
      if (e.target.closest('.win-btn')) return;
      const win = bar.closest('.window');
      dragging = true;
      const rect = win.getBoundingClientRect();
      ox = e.clientX - rect.left;
      oy = e.clientY - rect.top;
      focusWindow(win);
      e.preventDefault();
    });
    window.addEventListener('mousemove', (e) => {
      if (!dragging) return;
      const win = bar.closest('.window');
      let nx = e.clientX - ox;
      let ny = e.clientY - oy;
      ny = Math.max(28, ny);
      win.style.left = nx + 'px';
      win.style.top = ny + 'px';
    });
    window.addEventListener('mouseup', () => { dragging = false; });
  });

  /* ---------- Filesystem ---------- */
  const FS = {
    '/': { type: 'dir', children: ['bin', 'etc', 'home', 'usr', 'var', 'tmp', 'opt'] },
    '/bin': { type: 'dir', children: ['bash', 'ls', 'cat', 'cp', 'mv', 'rm', 'grep', 'echo'] },
    '/etc': { type: 'dir', children: ['passwd', 'hosts', 'hostname', 'os-release', 'fstab', 'apt'] },
    '/etc/apt': { type: 'dir', children: ['sources.list'] },
    '/home': { type: 'dir', children: ['user'] },
    '/home/user': { type: 'dir', children: ['Documents', 'Downloads', 'Pictures', 'Music', 'Desktop', '.bashrc'] },
    '/home/user/Documents': { type: 'dir', children: ['readme.txt', 'notes.md', 'report.odt'] },
    '/home/user/Downloads': { type: 'dir', children: ['installer.deb', 'archive.tar.gz'] },
    '/home/user/Pictures': { type: 'dir', children: ['vacation.jpg', 'screenshot.png', 'wallpaper.svg'] },
    '/home/user/Music': { type: 'dir', children: ['song.ogg'] },
    '/home/user/Desktop': { type: 'dir', children: [] },
    '/usr': { type: 'dir', children: ['bin', 'lib', 'share', 'local'] },
    '/usr/bin': { type: 'dir', children: ['python3', 'node', 'gcc', 'make'] },
    '/usr/lib': { type: 'dir', children: [] },
    '/usr/share': { type: 'dir', children: ['fonts', 'icons', 'doc'] },
    '/usr/local': { type: 'dir', children: ['bin'] },
    '/usr/local/bin': { type: 'dir', children: [] },
    '/var': { type: 'dir', children: ['log', 'cache', 'tmp', 'www'] },
    '/var/log': { type: 'dir', children: ['syslog', 'auth.log', 'dpkg.log'] },
    '/var/cache': { type: 'dir', children: [] },
    '/var/tmp': { type: 'dir', children: [] },
    '/var/www': { type: 'dir', children: ['html'] },
    '/var/www/html': { type: 'dir', children: ['index.html'] },
    '/tmp': { type: 'dir', children: [] },
    '/opt': { type: 'dir', children: [] }
  };

  /* Mark files (entries that aren't dirs in FS) */
  function isDir(path) {
    return FS[path] && FS[path].type === 'dir';
  }

  function joinPath(base, name) {
    if (base === '/') return '/' + name;
    return base + '/' + name;
  }

  function parentPath(path) {
    if (path === '/') return '/';
    const parts = path.split('/').filter(Boolean);
    parts.pop();
    return parts.length ? '/' + parts.join('/') : '/';
  }

  let currentPath = '/';

  const folderSvg = '<svg viewBox="0 0 48 48" fill="none"><path d="M6 14h14l3 3h19a2 2 0 012 2v19a2 2 0 01-2 2H6a2 2 0 01-2-2V16a2 2 0 012-2z" fill="#e8b84a"/><path d="M4 20h40v18a2 2 0 01-2 2H6a2 2 0 01-2-2V20z" fill="#f0c96a"/></svg>';
  const fileSvg = '<svg viewBox="0 0 48 48" fill="none"><path d="M12 4h16l10 10v28a2 2 0 01-2 2H12a2 2 0 01-2-2V6a2 2 0 012-2z" fill="#e8e8e8"/><path d="M28 4v10h10" fill="#ccc"/><rect x="16" y="22" width="16" height="2" rx="1" fill="#999"/><rect x="16" y="28" width="16" height="2" rx="1" fill="#999"/><rect x="16" y="34" width="10" height="2" rx="1" fill="#999"/></svg>';

  function renderListing() {
    const listing = document.getElementById('files-listing');
    const pathEl = document.getElementById('files-path');
    const upBtn = document.getElementById('files-up');
    pathEl.textContent = currentPath;
    upBtn.disabled = currentPath === '/';

    listing.innerHTML = '';
    const node = FS[currentPath];
    if (!node || !node.children) return;

    const children = node.children.slice().sort((a, b) => {
      const pa = joinPath(currentPath, a);
      const pb = joinPath(currentPath, b);
      const da = isDir(pa) ? 0 : 1;
      const db = isDir(pb) ? 0 : 1;
      if (da !== db) return da - db;
      return a.localeCompare(b);
    });

    children.forEach(name => {
      const full = joinPath(currentPath, name);
      const dir = isDir(full);
      const item = document.createElement('div');
      item.className = 'fs-item';
      item.dataset.name = name;
      item.dataset.path = full;
      item.dataset.dir = dir ? '1' : '0';
      item.innerHTML = '<div class="fs-icon">' + (dir ? folderSvg : fileSvg) + '</div><span></span>';
      item.querySelector('span').textContent = name;

      item.addEventListener('click', (e) => {
        listing.querySelectorAll('.fs-item').forEach(i => i.classList.remove('selected'));
        item.classList.add('selected');
      });

      item.addEventListener('dblclick', () => {
        if (dir) {
          currentPath = full;
          renderListing();
        }
      });

      listing.appendChild(item);
    });
  }

  document.getElementById('files-up').addEventListener('click', () => {
    if (currentPath === '/') return;
    currentPath = parentPath(currentPath);
    renderListing();
  });

  renderListing();

  /* ---------- Notepad / tabs + localStorage ---------- */
  const STORAGE_KEY = 'ubuntu-notepad-tabs-v1';
  let tabs = [];
  let activeTabId = null;
  let tabsReady = false;

  function uid() {
    return 't' + Date.now().toString(36) + Math.random().toString(36).slice(2, 7);
  }

  function loadTabs() {
    try {
      const raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        const data = JSON.parse(raw);
        if (data && Array.isArray(data.tabs) && data.tabs.length) {
          tabs = data.tabs;
          activeTabId = data.activeTabId && tabs.some(t => t.id === data.activeTabId)
            ? data.activeTabId
            : tabs[0].id;
          return;
        }
      }
    } catch (_) { /* ignore */ }
    tabs = [{ id: uid(), title: 'Untitled', content: '' }];
    activeTabId = tabs[0].id;
  }

  function saveTabs() {
    /* sync editor content into active tab first */
    const editor = document.getElementById('editor');
    const active = tabs.find(t => t.id === activeTabId);
    if (active && tabsReady) {
      active.content = editor.value;
    }
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify({ tabs, activeTabId }));
    } catch (_) { /* ignore quota */ }
  }

  function tabTitle(content, index) {
    const line = (content || '').split('\n')[0].trim();
    if (line) return line.slice(0, 24) + (line.length > 24 ? '…' : '');
    return 'Untitled ' + (index + 1);
  }

  function renderTabs() {
    const strip = document.getElementById('tabs');
    strip.innerHTML = '';
    tabs.forEach((tab, index) => {
      const el = document.createElement('div');
      el.className = 'tab' + (tab.id === activeTabId ? ' active' : '');
      el.dataset.id = tab.id;

      const label = document.createElement('span');
      label.textContent = tabTitle(tab.content, index);
      el.appendChild(label);

      const close = document.createElement('button');
      close.className = 'tab-close';
      close.title = 'Close tab';
      close.textContent = '×';
      close.addEventListener('click', (e) => {
        e.stopPropagation();
        closeTab(tab.id);
      });
      el.appendChild(close);

      el.addEventListener('click', () => switchTab(tab.id));
      strip.appendChild(el);
    });
  }

  function switchTab(id) {
    if (id === activeTabId) return;
    const editor = document.getElementById('editor');
    const prev = tabs.find(t => t.id === activeTabId);
    if (prev) prev.content = editor.value;

    activeTabId = id;
    const next = tabs.find(t => t.id === activeTabId);
    editor.value = next ? next.content : '';
    renderTabs();
    saveTabs();
  }

  function closeTab(id) {
    const editor = document.getElementById('editor');
    const cur = tabs.find(t => t.id === activeTabId);
    if (cur) cur.content = editor.value;

    const idx = tabs.findIndex(t => t.id === id);
    if (idx === -1) return;

    tabs.splice(idx, 1);
    if (!tabs.length) {
      const t = { id: uid(), title: 'Untitled', content: '' };
      tabs.push(t);
      activeTabId = t.id;
      editor.value = '';
    } else if (activeTabId === id) {
      const newIdx = Math.min(idx, tabs.length - 1);
      activeTabId = tabs[newIdx].id;
      editor.value = tabs[newIdx].content;
    }
    renderTabs();
    saveTabs();
  }

  function createTab() {
    const editor = document.getElementById('editor');
    const prev = tabs.find(t => t.id === activeTabId);
    if (prev) prev.content = editor.value;

    const t = { id: uid(), title: 'Untitled', content: '' };
    tabs.push(t);
    activeTabId = t.id;
    editor.value = '';
    renderTabs();
    saveTabs();
    editor.focus();
  }

  function ensureTabsLoaded() {
    if (tabsReady) return;
    loadTabs();
    const editor = document.getElementById('editor');
    const active = tabs.find(t => t.id === activeTabId) || tabs[0];
    activeTabId = active.id;
    editor.value = active.content || '';
    renderTabs();
    tabsReady = true;
  }

  document.getElementById('new-tab').addEventListener('click', () => {
    ensureTabsLoaded();
    createTab();
  });

  const editor = document.getElementById('editor');
  editor.addEventListener('input', () => {
    const active = tabs.find(t => t.id === activeTabId);
    if (active) {
      active.content = editor.value;
      renderTabs();
      saveTabs();
    }
  });

  /* Persist on page unload */
  window.addEventListener('beforeunload', saveTabs);

  /* Load tabs immediately so reload restores even before opening notepad */
  ensureTabsLoaded();
})();
</script>
</body>
